        runtime=await root.Study40.mount({container:studyContainer,data,config,serverCondition:root.CONDITION,adapter:{
          validateSession:async envelope=>root.CANDOR_STUDY40_VALIDATE_SESSION(envelope),
          record:async response=>{if(live){const answer=await root.CANDOR_STUDY40_VALIDATE_RESPONSE(response);if(answer?.accepted!==true)throw Error('Your response could not be saved. Please try again.');}},
          advance:response=>{if(response.record_type==='audio_setup'&&!response.audible_confirmed){setupFailed=true;done=true;}runtime?.stop();jsPsych.finishTrial(response);},
          complete:completion=>{done=true;runtime?.stop();jsPsych.finishTrial(completion);},
          decline:record=>{declined=true;done=true;runtime?.stop();jsPsych.finishTrial(record);}
        }});
