          const saved=[runtime.state.audio_setup,...(runtime.state.practice_responses||[]),...runtime.state.responses].filter(response=>response&&(!pendingId||response.response_id!==pendingId)).sort((a,b)=>String(a.started_at||'').localeCompare(String(b.started_at||'')));
